  "public/styles/about.css": ".flex {\n\tmargin: 0;\n\tpadding: 0;\n\tbox-sizing: border-box;\n}\n\n.header {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 1rem;\n\tmargin-top: 1em;\n\tflex-wrap: wrap;\n}\n\n.header h3 {\n\tmax-width: 400px;\n}\n\n.flex {\n\tlist-style: 0;\n\tmargin: 0.5em 0;\n}\n\n.flex li {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 0.3em;\n\tmargin-top: 0.3em;\n}\n\n.profile {\n\twidth: 200px;\n\theight: auto;\n\tmax-width: 100%;\n\tobject-fit: contain;\n\tborder-radius: 15px;\n\tflex-shrink: 0;\n\tz-index: 1;\n}\n\n@media screen and (max-width: 768px) {\n\t.header {\n\t\tflex-direction: column;\n\t\talign-items: center;\n\t\ttext-align: center;\n\t}\n\n\t.flex li {\n\t\tjustify-content: center;\n\t}\n\n\t.header h3 {\n\t\tmax-width: 100%;\n\t}\n}\n",
